// === Tab: mySketch.js ===
let vmin;
let glsl;
let img, imgAspect;

function preload() {
  glsl = loadShader('https://openprocessing.org/sketch/1370022/files/shader.vert', 'shader.frag');
  img = loadImage('https://openprocessing.org/sketch/1370022/files/letter.jpg');
}

function setup() {
  createCanvas(1112, 834, WEBGL);
  noStroke();
  vmin = max(width, height);
  camera(vmin, -vmin, vmin);
  imgAspect = img.width / img.height;
}

function draw() {
	translate(150, -300, 300);
  let sec = millis() / 1000;
  let size = vmin;

  background(20);

  push();
  {
    shader(glsl);
    glsl.setUniform('uTime', sec);
    glsl.setUniform('uSize', size);
    glsl.setUniform('uTwist', PI);
    glsl.setUniform('uTwistOffset', -PI);
    glsl.setUniform('uTex', img);
    scale(size, size, size);
    plane(imgAspect, 1, 32, 32);
  }
  pop();
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  }
}

// === Tab: shader.vert ===
attribute vec3 aPosition;
attribute vec2 aTexCoord;
attribute vec3 aNormal;

uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;
uniform float uTime;
uniform float uSize;
uniform float uTwist;
uniform float uTwistOffset;

varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;

  vec3 pos = aPosition;
  float l = length(pos.xz);
  float angle = atan(pos.z, pos.x);
  float angleOffset = sin((pos.y / (uSize / 2.)) * 200.0 + uTime) * uTwist + uTwistOffset;
  float a = angle + angleOffset;
  pos.x = cos(a) * l;
  pos.z = sin(a) * l;

  vec4 position = vec4(pos, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * position;
}

// === Tab: shader.frag ===
precision mediump float;

varying vec2 vTexCoord;

uniform sampler2D uTex;

void main() {
  vec2 uv = vTexCoord;
  vec4 color = texture2D(uTex, uv);
  gl_FragColor = color;
}

